head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getColumnIncrement]<br/>Body Column 정보를 사용하여 특정 Column 의 increment 속성값을 반환합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 increment 속성을 조회할 Body Column 의 ID 를 설정할 수 있어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : text / spinner Column 을 섞어 구성한다. (columnInfo 를 Body Column 의 ID 로 조회)
//  - cname  : 품목  (text)               -> spinner 아님 -> false
//  - cspec  : 규격  (text, 숨김)          -> spinner 아님 -> false (ID 조회는 숨김과 무관)
//  - cqty   : 수량  (spinner, increment=1)     -> Number 1
//  - cprice : 단가  (spinner, increment=1000)  -> Number 1000
//  - crate  : 비율  (spinner, increment 미설정) -> undefined
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Body Column ID - cname(품목,text) / cspec(규격,text 숨김) / cqty(수량,spinner increment=1) / cprice(단가,spinner increment=1000) / crate(비율,spinner increment 미설정).\n[절차] columnInfo(ID) 선택 후 (getColumnIncrement 실행) 클릭. noexist 는 존재하지 않는 ID.\n[확인] spinner+increment 설정(cqty/cprice)=설정된 increment 값(Number) / spinner+increment 미설정(crate)=undefined / 비 spinner text(cname/cspec)=false / 없는ID(noexist)=false 가 반환영역에 출력됨."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="cname" name="cname" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cspec" name="cspec" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cqty" name="cqty" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cprice" name="cprice" dataType="text"></w2:column>';
    strDlt += '<w2:column id="crate" name="crate" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    dlt_bind.setJSON([
        { "cname": "노트북", "cspec": "15인치", "cqty": "10", "cprice": "1200000", "crate": "3" },
        { "cname": "모니터", "cspec": "27인치", "cqty": "20", "cprice": "350000", "crate": "5" },
        { "cname": "키보드", "cspec": "무선", "cqty": "30", "cprice": "45000", "crate": "8" }
    ], false);

    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (text / spinner 혼합)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:100%;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getColumnIncrement 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="120" inputType="text" id="h0" value="품목(text)"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="h1" value="규격(숨김)"></w2:column>';
    strTarget += '<w2:column width="130" inputType="text" id="h2" value="수량(spinner,inc=1)"></w2:column>';
    strTarget += '<w2:column width="150" inputType="text" id="h3" value="단가(spinner,inc=1000)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="h4" value="비율(spinner,inc 미설정)"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="brow1">';
    //  (중요) body 컬럼 id 는 dataList 컬럼 id 와 동일해야 셀에 데이터가 바인딩됨
    // cname : 품목 (text) -> spinner 아님 -> false
    strTarget += '<w2:column width="120" inputType="text" id="cname" dataList="cname"></w2:column>';
    // cspec : 규격 (text) -> setColumnVisible(1,false) 로 숨김 (ID 조회는 숨김과 무관) -> false
    strTarget += '<w2:column width="120" inputType="text" id="cspec" dataList="cspec"></w2:column>';
    // cqty : 수량 (spinner, increment=1) -> Number 1
    strTarget += '<w2:column width="130" inputType="spinner" id="cqty" dataList="cqty" increment="1"></w2:column>';
    // cprice : 단가 (spinner, increment=1000) -> Number 1000
    strTarget += '<w2:column width="150" inputType="spinner" id="cprice" dataList="cprice" increment="1000"></w2:column>';
    // crate : 비율 (spinner, increment 미설정) -> undefined
    strTarget += '<w2:column width="*" inputType="spinner" id="crate" dataList="crate"></w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 두번째 Column(규격) 숨김 -> ID 조회는 숨김과 무관하게 동작
    target1.setColumnVisible(1, false);
}



// getColumnIncrement 조회 (메인 검증 - ID)
//  - columnInfo 파라미터에 Body Column 의 ID 를 전달하여 조회
scwin.btn_getColumnIncrement_onclick = function () {
    let columnInfo = par_columnInfo.getValue();

    let colIndex = target1.getColumnIndex(columnInfo);
    let inc = target1.getColumnIncrement(columnInfo);

    let result;
    if (typeof inc === 'undefined') {
        result = "undefined (increment 미설정)";
    } else if (inc === false) {
        result = "false (비 spinner 또는 없는 컬럼)";
    } else {
        result = inc + " (typeof " + (typeof inc) + ", 설정된 increment)";
    }

    wf_body_bottom.getObj("scwin").setReturnValue("getColumnIncrement('" + columnInfo + "') [getColumnIndex:" + colIndex + "] -> " + result);
}
